(function(){
  let open; try{ open=JSON.parse(localStorage.getItem('safi_setopen')||'[]') }catch(e){ open=[] }
  document.querySelectorAll('#page-settings .set-grid > .card').forEach(c=>{
    const h=c.querySelector(':scope > h3'); if(!h) return;
    const key=h.textContent.trim();
    const set=on=>{ c.classList.toggle('collapsed',!on); h.setAttribute('aria-expanded',on?'true':'false'); tg.textContent=on?'▾':'▸' };
    h.classList.add('set-h'); h.setAttribute('role','button'); h.tabIndex=0;
    const tg=document.createElement('span'); tg.className='colbtn'; tg.setAttribute('aria-hidden','true'); h.appendChild(tg);
    set(open.includes(key));
    const flip=()=>{
      const on=c.classList.contains('collapsed'); set(on);
      open=open.filter(k=>k!==key); if(on) open.push(key);
      try{ localStorage.setItem('safi_setopen',JSON.stringify(open)) }catch(e){}
    };
    h.addEventListener('click',e=>{ if(e.target.closest('button:not(.colbtn),input,select,a')) return; flip() });
    h.addEventListener('keydown',e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); flip() } });
  });
})();
